const profile = $('GetUserProfile').item.json;

// ============================================
// FUNCION: parseHomeEquipment
// PROPOSITO: Parsear equipamiento disponible en casa
// INPUT: String con equipamiento separado por comas (espanol)
// OUTPUT: Objeto con arrays y flags para queries
// ============================================

function parseHomeEquipment(equipmentStr, environment) {
  // Si es GYM, retornar configuracion que no filtra
  if (!environment || environment.toUpperCase() === 'GYM') {
    return {
      is_home: false,
      equipment_list: [], // Vacio = no filtrar
      home_equipment_sql: null,
      has_pull_bar: true, // Asumimos acceso a todo en gym
      has_barbell: true,
      has_dumbbells: true,
      has_kettlebells: true,
      has_bench: true,
      has_bands: true,
      equipment_tier: 'full'
    };
  }

  // Mapeo espanol -> canonico (valores en BD)
  const equipmentMap = {
    // Mancuernas
    'mancuernas': 'dumbbell',
    'mancuerna': 'dumbbell',
    'dumbbells': 'dumbbell',
    'dumbbell': 'dumbbell',
    'pesas': 'dumbbell',

    // Kettlebells
    'kettlebell': 'kettlebell',
    'kettlebells': 'kettlebell',
    'pesa rusa': 'kettlebell',
    'pesas rusas': 'kettlebell',

    // Barra/Barbell
    'barra': 'barbell',
    'barras': 'barbell',
    'barbell': 'barbell',
    'barra olimpica': 'barbell',
    'barra olímpica': 'barbell',

    // Barra de dominadas
    'barra de dominadas': 'pull_bar',
    'barra dominadas': 'pull_bar',
    'pull up bar': 'pull_bar',
    'pullup bar': 'pull_bar',
    'barra para dominadas': 'pull_bar',

    // Bandas
    'bandas': 'bands',
    'bandas elasticas': 'bands',
    'bandas elásticas': 'bands',
    'ligas': 'bands',
    'resistance bands': 'bands',

    // Banco
    'banco': 'bench',
    'banco plano': 'bench',
    'banco ajustable': 'bench'
  };

  // Parsear string de entrada
  const normalized = (equipmentStr || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, ''); // Remover acentos

  const equipmentSet = new Set(['bodyweight']); // Siempre incluir bodyweight
  const flags = {
    has_pull_bar: false,
    has_barbell: false,
    has_dumbbells: false,
    has_kettlebells: false,
    has_bench: false,
    has_bands: false
  };

  // Buscar matches en el texto
  for (const [spanish, canonical] of Object.entries(equipmentMap)) {
    const normalizedSpanish = spanish
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g, '');

    if (normalized.includes(normalizedSpanish)) {
      if (canonical === 'pull_bar') {
        flags.has_pull_bar = true;
        // pull_bar habilita ejercicios bodyweight de pull_v
      } else if (canonical === 'bands') {
        flags.has_bands = true;
        equipmentSet.add('resistance_band'); // Agregar resistance_band al filtro SQL
      } else if (canonical === 'bench') {
        flags.has_bench = true;
      } else {
        equipmentSet.add(canonical);
        if (canonical === 'barbell') flags.has_barbell = true;
        if (canonical === 'dumbbell') flags.has_dumbbells = true;
        if (canonical === 'kettlebell') flags.has_kettlebells = true;
      }
    }
  }

  const equipmentList = Array.from(equipmentSet);

  // Generar SQL para filtrado
  // Formato: 'bodyweight', 'dumbbell', 'kettlebell'
  const home_equipment_sql = equipmentList
    .map(e => `'${e}'`)
    .join(', ');

  // Determinar tier de equipamiento
  let equipment_tier = 'minimal'; // Solo bodyweight
  if (flags.has_dumbbells || flags.has_kettlebells) {
    equipment_tier = 'basic'; // Peso libre basico
  }
  if (flags.has_barbell) {
    equipment_tier = 'intermediate'; // Tiene barra
  }
  if (flags.has_barbell && flags.has_dumbbells && flags.has_pull_bar) {
    equipment_tier = 'advanced'; // Home gym completo
  }

  return {
    is_home: true,
    equipment_list: equipmentList,
    home_equipment_sql: home_equipment_sql,
    has_pull_bar: flags.has_pull_bar,
    has_barbell: flags.has_barbell,
    has_dumbbells: flags.has_dumbbells,
    has_kettlebells: flags.has_kettlebells,
    has_bench: flags.has_bench,
    has_bands: flags.has_bands,
    equipment_tier: equipment_tier
  };
}

// Diccionario de mapeo espanol -> ingles
const muscleMap = {
  "abdomen": ["Abs", "Core"],
  "abdominales": ["Abs"],
  "espalda": ["Back"],
  "pecho": ["Chest"],
  "gluteo": ["Glutes"],
  "glúteo": ["Glutes"],
  "gluteos": ["Glutes"],
  "glúteos": ["Glutes"],
  "pierna": ["Quads", "Hamstrings", "Glutes", "Calfs"],
  "piernas": ["Quads", "Hamstrings", "Glutes", "Calfs"],
  "cuadriceps": ["Quads"],
  "cuádriceps": ["Quads"],
  "femorales": ["Hamstrings"],
  "isquiotibiales": ["Hamstrings"],
  "pantorrillas": ["Calfs"],
  "hombros": ["Shoulders"],
  "hombro": ["Shoulders"],
  "biceps": ["Biceps"],
  "bíceps": ["Biceps"],
  "triceps": ["Triceps"],
  "tríceps": ["Triceps"],
  "brazos": ["Biceps", "Triceps", "Forearms"],
  "antebrazos": ["Forearms"],
  "trapecio": ["Traps"],
  "espalda baja": ["Lower back"],
  "lumbar": ["Lower back"],
  "lumbares": ["Lower back"]
};

function mapMuscles(spanishText) {
  if (!spanishText || spanishText.toLowerCase().includes('todo') || spanishText.toLowerCase().includes('ninguno') || spanishText.toLowerCase().includes('no tengo')) {
    return [];
  }
  const normalized = spanishText.toLowerCase()
    .normalize("NFD").replace(/[\u0300-\u036f]/g, ""); // Remove accents
  const results = new Set();

  for (const [spanish, english] of Object.entries(muscleMap)) {
    const normalizedSpanish = spanish.normalize("NFD").replace(/[\u0300-\u036f]/g, "");
    if (normalized.includes(normalizedSpanish)) {
      (Array.isArray(english) ? english : [english]).forEach(m => results.add(m));
    }
  }
  return Array.from(results);
}

function getExperienceTier(exp) {
  if (!exp) return 'intermediate';
  if (['Nunca he entrenado', 'Menos de 6 meses'].includes(exp)) return 'beginner';
  if (['Mas de 3 anos', 'Más de 3 años'].includes(exp)) return 'advanced';
  return 'intermediate';
}

function getVolumeModifier(duration) {
  if (!duration) return 1.0;
  if (duration === '45-60 minutos' || duration.includes('45')) return 0.85;
  if (duration === 'Mas de 75 minutos' || duration.includes('75') || duration.includes('90')) return 1.15;
  return 1.0;
}

function getHealthRestrictions(status) {
  return {
    has_restrictions: ['B', 'C', 'D', 'E'].includes(status),
    avoid_lower_body_impact: status === 'B',
    avoid_upper_body_overhead: status === 'C',
    avoid_spinal_loading: status === 'D',
    special_condition: status === 'E'
  };
}

// Obtener environment del perfil (nuevo campo de users_gym_profile)
const environment = profile.training_environment || 'GYM';
const homeEquipment = parseHomeEquipment(profile.home_equipment, environment);

return [{
  json: {
    ...profile,
    processed: {
      // Campos existentes (NO MODIFICAR)
      priority_muscles_en: mapMuscles(profile.priority_muscles),
      disliked_muscles_en: mapMuscles(profile.disliked_exercises),
      experience_tier: getExperienceTier(profile.training_experience),
      volume_modifier: getVolumeModifier(profile.session_duration_mins),
      health: getHealthRestrictions(profile.health_status),

      // === NUEVOS CAMPOS PARA HOME ===
      environment: environment.toUpperCase(),
      home: homeEquipment
    }
  }
}];

const week1Exercises = $("Code in JavaScript").all().map(item => item.json);
const allProfiles = $input.all().map(item => item.json);

// Role priority: compound first, then core, then isolation
const rolePriority = { compound: 1, core: 2, isolation: 3 };

// Group exercises by day_name
const exercisesByDay = {};
for (const ex of week1Exercises) {
  if (!exercisesByDay[ex.day_name]) {
    exercisesByDay[ex.day_name] = [];
  }
  exercisesByDay[ex.day_name].push(ex);
}

// Sort each day's exercises by role priority, then assign exercise_order
const sortedExercises = [];
for (const dayName of Object.keys(exercisesByDay)) {
  const dayExercises = exercisesByDay[dayName];
  // Sort by role: compound (1) -> core (2) -> isolation (3)
  dayExercises.sort((a, b) => {
    const priorityA = rolePriority[a.role?.toLowerCase()] || 4;
    const priorityB = rolePriority[b.role?.toLowerCase()] || 4;
    return priorityA - priorityB;
  });
  // Assign sequential exercise_order
  dayExercises.forEach((ex, index) => {
    ex.exercise_order = index + 1;
  });
  sortedExercises.push(...dayExercises);
}

let full4WeekPlan = [];

for (const ex of sortedExercises) {
  for (let w = 1; w <= 4; w++) {
    // Buscamos el perfil comparando texto limpio
    const profile = allProfiles.find(p => 
      p.goal?.toString().trim().toLowerCase() === ex.goal?.toString().trim().toLowerCase() &&
      p.level?.toString().trim().toLowerCase() === ex.level?.toString().trim().toLowerCase() &&
      p.role?.toString().trim().toLowerCase() === ex.role?.toString().trim().toLowerCase() &&
      p.week?.toString() === w.toString()
    );

    if (profile) {
      full4WeekPlan.push({
        ...ex,
        week_number: w,
        sets: profile.sets,
        reps: profile.reps,
        rir: profile.rir,
        rest_seconds: profile.rest_sec,
        tempo: profile.tempo,
        notes: profile.notes || ""
      });
    } else {
      // Diagnóstico: Te dirá qué intentó buscar
      full4WeekPlan.push({
        ...ex,
        week_number: w,
        notes: `No match para: ${ex.goal} | ${ex.level} | ${ex.role} | Sem:${w}`
      });
    }
  }
}

// Return each workout as a separate item
return full4WeekPlan.map(workout => ({ json: workout }));

const items = $input.all();
const unifiedArray = items.map((item) => item.json);
return [{ json: { unifiedArray }, pairedItem: items.map((_, index) => index) }];

// Arreglo para acumular todos los ejercicios finales
let allExercises = [];

// Recorremos los ítems de entrada (usualmente es 1 que contiene el unifiedArray)
for (const item of $input.all()) {
  const unified = item.json.unifiedArray;
  if (Array.isArray(unified)) {
    for (const entry of unified) {
      try {
        let outputStr = entry.output;

        // Limpiar los bloques de código markdown (```json ... ```)
        outputStr = outputStr
          .replace(/^```json\s*/i, '')  // Quitar ```json del inicio
          .replace(/^```\s*/i, '')       // O solo ``` del inicio
          .replace(/\s*```$/i, '')       // Quitar ``` del final
          .trim();

        // Parseamos el string limpio
        const exercises = JSON.parse(outputStr);

        // Agregamos los ejercicios al arreglo maestro
        allExercises.push(...exercises);
      } catch (error) {
        // Ignoramos errores de parseo si algún output viene mal
        continue;
      }
    }
  }
}

// Retornamos cada ejercicio como un ítem independiente para n8n
return allExercises.map(exercise => ({ json: exercise }));

